namespace PhotoBooth.Customer.UI.Workflow { public sealed class CustomerWorkflowContext { public Settings Settings{get;set;}public Session Session{get;set;}public string CaptureId{get;set;}public string WorkingDirectory{get;set;}public List<CapturedShot> CurrentShots{get;set;}=new List<CapturedShot>();public CameraInfo Camera{get;set;}public Frame SelectedFrame{get;set;}public Preset DefaultPreset{get;set;}public bool CameraDisconnectedPending{get;set;}public bool PrintingEnabled{get;set;}public string ConnectedPrinterId{get;set;}public void ResetForNewSession(){Settings=null;Session=null;CaptureId=null;WorkingDirectory=null;CurrentShots?.Clear();Camera=null;SelectedFrame=null;DefaultPreset=null;CameraDisconnectedPending=false;PrintingEnabled=false;ConnectedPrinterId=null;} } }
